-- Rollback-only fixtures: no real users, messages or map changes are retained.
begin;
do $$
declare a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();outsider uuid:=gen_random_uuid();ca uuid:=gen_random_uuid();cb uuid:=gen_random_uuid();va uuid:=gen_random_uuid();vb uuid:=gen_random_uuid();late uuid:=gen_random_uuid();mid uuid:=gen_random_uuid();badge uuid:=gen_random_uuid();req uuid:=gen_random_uuid();wid text:='test-'||gen_random_uuid();w2 text:='test-'||gen_random_uuid();rid text;result jsonb;counted int;img text:='data:image/jpeg;base64,/9j/2Q==';
begin
 insert into auth.users(id,raw_user_meta_data) values(a,'{"username":"Playtest Admin"}'),(b,'{"username":"Playtest Member"}'),(outsider,'{"username":"Playtest Outsider"}');
 insert into public.worlds(id,name) values(wid,'Test World'),(w2,'Other Test World');
 insert into public.world_regions values(wid,'r','Test Region'),(w2,'r','Other Region');
 insert into public.world_locations(world_id,id,region_id,name,map_x,map_y) values(wid,'a','r','Room A',0,0),(wid,'b','r','Room B',1,0),(wid,'c','r','Room C',2,0),(w2,'a','r','Other room',0,0);
 insert into public.room_connections(world_id,from_room,to_room) values(wid,'a','b'),(wid,'b','a'),(wid,'b','c'),(wid,'c','b');
 insert into public.world_staff values(wid,a,'Lead Admin');
 insert into public.characters(id,player_id,world_id,slot,name,room_id) values(ca,a,wid,1,'Alice','a'),(cb,b,wid,1,'Bob','a');
 perform set_config('request.jwt.claim.sub',a::text,true);perform public.enter_chat(va,ca,'a');
 perform set_config('request.jwt.claim.sub',b::text,true);perform public.enter_chat(vb,cb,'a');
 perform set_config('request.jwt.claim.sub',a::text,true);
 perform public.set_chat_typing(va,true);
 if not (public.room_snapshot(ca)->'characters' @> jsonb_build_array(jsonb_build_object('id',ca,'typing',true))) then raise exception 'Typing missing';end if;
 perform public.send_chat_message(mid,va,'Picture','ic',array[img]);
 perform public.send_chat_message(mid,va,'Picture','ic',array[img]);
 if (select count(*) from public.room_message_images where message_id=mid)<>1 then raise exception 'Image retry duplicated';end if;
 begin perform public.send_chat_message(gen_random_uuid(),va,'Too soon','ooc',array[img]);raise exception 'Image cooldown bypass';exception when others then if sqlerrm not like 'Please slow down.%' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',b::text,true);execute 'set local role authenticated';
 select count(*) into counted from public.room_message_images where message_id=mid;if counted<>1 then raise exception 'Witness cannot read image';end if;
 execute 'reset role';perform set_config('request.jwt.claim.sub',outsider::text,true);execute 'set local role authenticated';
 select count(*) into counted from public.room_message_images where message_id=mid;if counted<>0 then raise exception 'Image privacy leak';end if;
 execute 'reset role';
 update public.room_messages set created_at=clock_timestamp()-interval '25 hours' where id=mid;
 perform set_config('request.jwt.claim.sub',b::text,true);execute 'set local role authenticated';
 select count(*) into counted from public.room_message_images where message_id=mid;if counted<>0 then raise exception 'Expired image readable';end if;
 execute 'reset role';delete from public.room_messages where id=mid;
 if exists(select 1 from public.room_message_images where message_id=mid) then raise exception 'Image deletion did not cascade';end if;
 perform set_config('request.jwt.claim.sub',a::text,true);
 perform public.save_character_location(ca,'a','b');
 if not exists(select 1 from public.room_messages where world_id=wid and message_type='movement' and body='Alice leaves for Room B.' and vb=any(visit_ids) and not(va=any(visit_ids))) then raise exception 'Departure audience';end if;
 va:=gen_random_uuid();perform public.enter_chat(va,ca,'b');perform public.sneak_character(req,va);perform public.sneak_character(req,va);
 select count(*) into counted from public.room_messages where world_id=wid and message_type='movement';
 perform public.save_character_location(ca,'b','a');
 if (select count(*) from public.room_messages where world_id=wid and message_type='movement')<>counted then raise exception 'Sneak did not suppress notice';end if;
 -- Stale/disabled door references must not lock an unrelated passage.
 insert into public.world_doors(world_id,door_id,inside_room,outside_room,enabled,locked) values(wid,'c','c','b',false,true);
 update public.room_connections set door_id='c' where world_id=wid and from_room='a' and to_room='b';
 perform public.save_character_location(ca,'a','b');
 perform public.connect_world_rooms(wid,'a','c',true);
 if (select count(*) from public.room_connections where world_id=wid and from_room='a')<>2 then raise exception 'Multiple connections not saved';end if;
 rid:=public.create_owned_world_room(gen_random_uuid(),wid,'c','top','Owned room','Home',cb);
 perform set_config('request.jwt.claim.sub',b::text,true);
 perform public.edit_owned_room(cb,rid,'My home',null);
 begin perform public.edit_owned_room(cb,'a','Not mine',null);raise exception 'Owner scope bypass';exception when others then if sqlerrm<>'This character does not own this room' then raise;end if;end;
 begin perform public.admin_teleport(cb,'c');raise exception 'Teleport bypass';exception when others then if sqlerrm<>'Admin permission required for this world' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',a::text,true);perform public.admin_teleport(ca,'c');
 if (select room_id from public.characters where id=ca)<>'c' then raise exception 'Teleport failed';end if;
 update public.world_doors set enabled=true,locked=true where world_id=wid and door_id='c';
 update public.room_connections set door_id='c' where world_id=wid and from_room in('b','c') and to_room in('b','c');
 begin perform public.change_door(ca,'c',true);raise exception 'Inside lock without key';exception when others then if sqlerrm<>'A matching key is required' then raise;end if;end;
 insert into public.character_items(character_id,kind,slot,key_room) values(ca,'key',1,'c');
 perform public.change_door(ca,'c',true);
 perform public.save_character_location(ca,'c','b');
 if not (select locked from public.world_doors where world_id=wid and door_id='c') then raise exception 'Exiting changed lock state';end if;
 begin perform public.save_character_location(ca,'b','c');raise exception 'Locked entry allowed';exception when others then if sqlerrm<>'The door is locked' then raise;end if;end;
 delete from public.character_items where character_id=ca;
 begin perform public.change_door(ca,'c',true);raise exception 'Outside lock without key';exception when others then if sqlerrm<>'A matching key is required' then raise;end if;end;
 insert into public.character_items(character_id,kind,slot,key_room) values(ca,'key',1,'c');
 perform public.change_door(ca,'c',true);
 perform public.admin_teleport(ca,'c');
 if not exists(select 1 from jsonb_array_elements(public.world_map(wid)->'rooms') r where r->>'id'=rid and r->>'owner_name'='Bob') then raise exception 'Room owner display missing';end if;
 perform public.save_world_badge(badge,wid,'Explorer','#347797','Explores');perform public.award_world_badge(wid,badge,b,true);
 if public.staff_rank(wid,b)<>0 then raise exception 'Decorative badge grants authority';end if;
 if public.player_profile_extras(b)->'badges' @> '["Explorer"]'::jsonb then raise exception 'World badge leaked globally';end if;
 begin perform public.save_world_badge(gen_random_uuid(),w2,'Outsider','#347797','');raise exception 'Badge crossed world';exception when others then if sqlerrm<>'Admin permission required for this world' then raise;end if;end;
 if public.can_view_character(cb) then raise exception 'Remote character profile visible';end if;
 va:=gen_random_uuid();perform public.admin_teleport(ca,'a');perform public.enter_chat(va,ca,'a');
 if not public.can_view_character(cb) then raise exception 'Nearby character hidden';end if;
 if has_function_privilege('anon','public.send_chat_message(uuid,uuid,text,text,text[])','execute') or has_function_privilege('authenticated','public.room_departure(uuid,text)','execute') then raise exception 'Private function permissions';end if;
end $$;
rollback;
select 'PASS: typing, image cooldown/retry/RLS/expiry/deletion, movement notices, sneak, free exit/locked entry/key checks, exact door edges, multiple connections, room ownership, teleport permission, world badge scope, nearby profile privacy' as result;
